if (rawActions.length === 0) throw new Error('At least one action is required.');
const actions = rawActions.map((a, i) => {
  if (!VALID_ACTION_TYPES.includes(a.action_type)) throw new Error(`Action ${i + 1}: invalid action_type.`);
  return {
    branch: (a.branch || 'default').toString(),
    action_type: a.action_type,
    action_config: a.action_config || {},
    sort_order: i,
  };
});

return [{ json: { id, name, triggerType, triggerConfig, conditionTree, actions, requesterId: requester.id } }];

