const automationId = $('Upsert Automation').first().json.id;
const actions = $('Validate & Payload (Save)').first().json.actions;
return actions.map((a) => ({ json: { automationId, ...a } }));

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');
return [{ json: { requesterId: parseInt(match[1], 10) } }];

const requester = $input.first().json;
const body = $('Webhook - Update Automation Active').first().json.body || {};
if (!requester.id || !requester.active) throw new Error('Invalid session.');
const id = parseInt(body.id, 10);
if (!Number.isInteger(id)) throw new Error('"id" must be an integer.');
if (typeof body.is_active !== 'boolean') throw new Error('"is_active" must be true or false.');
return [{ json: { id, isActive: body.is_active } }];

const result = $input.first();
if (!result || !result.json || !result.json.id) throw new Error('Automation not found.');
return [{ json: { success: true } }];

