const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');
return [{ json: { requesterId: parseInt(match[1], 10) } }];

const requester = $input.first().json;
const body = $('Webhook - Test Automation').first().json.body || {};
if (!requester.id || !requester.active) throw new Error('Invalid session.');

const VALID_TRIGGER_TYPES = ['contact', 'company', 'task', 'calendar', 'pipeline'];
const VALID_ACTION_TYPES = ['add_tag', 'send_email', 'send_team_notification', 'send_sms'];

const id = body.id ? parseInt(body.id, 10) : null;
const name = (body.name || '').toString().trim();
const triggerType = (body.trigger_type || '').toString();
if (!name) throw new Error('"name" is required.');
if (!VALID_TRIGGER_TYPES.includes(triggerType)) throw new Error('"trigger_type" is invalid.');

const triggerConfig = body.trigger_config;
if (!triggerConfig || !triggerConfig.field || !triggerConfig.operator || triggerConfig.value === undefined || triggerConfig.value === '') {
  throw new Error('A fully configured trigger is required.');
}

const conditionTree = (body.condition_tree && body.condition_tree.field) ? body.condition_tree : null;

const rawActions = Array.isArray(body.actions) ? body.actions : [];
if (rawActions.length === 0) throw new Error('At least one action is required.');
const actions = rawActions.map((a, i) => {
  if (!VALID_ACTION_TYPES.includes(a.action_type)) throw new Error(`Action ${i + 1}: invalid action_type.`);
  return {
    branch: (a.branch || 'default').toString(),
    action_type: a.action_type,
    action_config: a.action_config || {},
    sort_order: i,
  };
});

const testEmail = (body.test_email || '').toString().trim() || null;
return [{ json: { id, name, triggerType, triggerConfig, conditionTree, actions, testEmail, requesterId: requester.id } }];

// Dry run: samples live rows for the chosen trigger_type and evaluates
// the condition tree in JS (Evaluate & Respond node) rather than
// executing any action. The sample is NOT filtered by the trigger
// condition in SQL (conditions are evaluated generically in JS, same as
// the Engine), so the LIMIT here has to be generous — a tight LIMIT
// combined with `ORDER BY id DESC` would silently miss the one record
// an admin is actually testing against if it isn't among the newest
// rows. This runs only when a human clicks Test, not on a poll, so a
// few hundred rows is an acceptable cost. Task/Calendar/Pipeline all
// join back to `contacts` for first_name/last_name/email so merge
// fields resolve the same way they do in Automation Engine.json's
// Build Candidate Query — Company triggers have no single associated
// contact, so those stay null. Task and Calendar both read from
// `activities` (see src/types/event.ts) — there is no separate
// calendar_events table in this schema.
const p = $input.first().json;
const SAMPLE_LIMIT = 200;
// owner_name resolves the {{owner_name}} merge token, same columns as
// Automation Engine.json's Build Candidate Query.
const queries = {
  contact: `SELECT c.id, c.first_name, c.last_name, c.email, c.lead_status, c.birthdate, c.city, c.state, c.country, ow.name AS owner_name,
      (SELECT COALESCE(json_agg(t.name), '[]'::json) FROM tags t JOIN taggables tg ON tg.tag_id = t.id WHERE tg.entity_type = 'contact' AND tg.entity_id = c.id) AS tags
    FROM contacts c LEFT JOIN users ow ON ow.id = c.owner_id WHERE c.is_archived = false ORDER BY c.id DESC LIMIT ${SAMPLE_LIMIT};`,
  company: `SELECT co.id, co.name, NULL::text AS first_name, NULL::text AS last_name, NULL::text AS email, ow.name AS owner_name,
      co.account_status, co.city, co.state, co.country, co.annual_revenue, co.employee_count,
      (SELECT COALESCE(json_agg(t.name), '[]'::json) FROM tags t JOIN taggables tg ON tg.tag_id = t.id WHERE tg.entity_type = 'company' AND tg.entity_id = co.id) AS tags
    FROM companies co LEFT JOIN users ow ON ow.id = co.owner_id WHERE co.is_archived = false ORDER BY co.id DESC LIMIT ${SAMPLE_LIMIT};`,
  task: `SELECT act.id, act.subject AS name, ct.first_name, ct.last_name, ct.email, ow.name AS owner_name, act.is_completed, act.due_at
    FROM activities act
    LEFT JOIN contacts ct ON ct.id = act.contact_id
    LEFT JOIN users ow ON ow.id = act.user_id
    WHERE act.due_at IS NOT NULL ORDER BY act.id DESC LIMIT ${SAMPLE_LIMIT};`,
  calendar: `SELECT act.id, act.subject AS name, ct.first_name, ct.last_name, ct.email, ow.name AS owner_name, act.type, act.due_at, act.is_completed
    FROM activities act
    LEFT JOIN contacts ct ON ct.id = act.contact_id
    LEFT JOIN users ow ON ow.id = act.user_id
    WHERE act.due_at IS NOT NULL ORDER BY act.id DESC LIMIT ${SAMPLE_LIMIT};`,
  pipeline: `SELECT o.id, o.name, ct.first_name, ct.last_name, ct.email, ow.name AS owner_name, o.pipeline_id, o.stage_id, prop.public_token AS proposal_token
    FROM opportunities o
    LEFT JOIN contacts ct ON ct.id = o.contact_id
    LEFT JOIN users ow ON ow.id = o.assigned_user
    LEFT JOIN LATERAL (
      SELECT p.public_token FROM proposals p WHERE p.opportunity_id = o.id ORDER BY p.created_at DESC LIMIT 1
    ) prop ON true
    WHERE o.is_archived = false ORDER BY o.id DESC LIMIT ${SAMPLE_LIMIT};`,
};
const sqlQuery = queries[p.triggerType];
if (!sqlQuery) throw new Error('Unsupported trigger_type.');
return [{ json: { sqlQuery, queryParams: [] } }];

const rows = $input.all().map((i) => i.json);
const p = $('Validate & Payload (Test)').first().json;
const trigger = p.triggerConfig;
const condition = p.conditionTree;
const actions = p.actions;

function getFieldValue(row, field) {
  if (field === 'age') {
    if (!row.birthdate) return null;
    const ms = Date.now() - new Date(row.birthdate).getTime();
    return Math.floor(ms / (365.25 * 24 * 3600 * 1000));
  }
  if (field === 'overdue') {
    return !row.is_completed && row.due_at && new Date(row.due_at) < new Date();
  }
  if (field === 'location') {
    return [row.city, row.state, row.country].filter(Boolean).join(', ');
  }
  return row[field];
}

function evalCondition(row, cond) {
  if (!cond || !cond.field) return true;
  const actual = getFieldValue(row, cond.field);
  const expected = cond.value;
  switch (cond.operator) {
    case 'equals': return Array.isArray(actual) ? actual.includes(expected) : String(actual) === String(expected);
    case 'not_equals': return Array.isArray(actual) ? !actual.includes(expected) : String(actual) !== String(expected);
    case 'contains': return String(actual || '').toLowerCase().includes(String(expected).toLowerCase());
    case 'greater_than': { const n = Number(actual); return Number.isFinite(n) ? n > Number(expected) : new Date(actual) > new Date(expected); }
    case 'less_than': { const n = Number(actual); return Number.isFinite(n) ? n < Number(expected) : new Date(actual) < new Date(expected); }
    case 'is_true': return Boolean(actual) === true;
    case 'is_false': return Boolean(actual) === false;
    default: return false;
  }
}

let matched = null;
let branch = null;
for (const row of rows) {
  if (!evalCondition(row, trigger)) continue;
  matched = row;
  branch = condition ? (evalCondition(row, condition) ? 'true' : 'false') : 'default';
  break;
}

const actionsWouldRun = matched
  ? actions.filter((a) => a.branch === branch).map((a) => ({
      action_type: a.action_type,
      status: (a.action_type === 'send_team_notification' || a.action_type === 'send_sms') ? 'unsupported' : 'would_run',
    }))
  : [];

const emailAction = matched ? (actions.filter((a) => a.branch === branch).find((a) => a.action_type === 'send_email') || null) : null;

return [{
  json: {
    matched: !!matched,
    branch,
    sample_entity: matched
      ? { id: matched.id, label: matched.name || [matched.first_name, matched.last_name].filter(Boolean).join(' ') || `#${matched.id}` }
      : null,
    actions_would_run: actionsWouldRun,
    test_email_sent: false,
    _shouldSendTestEmail: Boolean(p.testEmail) && Boolean(emailAction),
    _testEmail: p.testEmail || null,
    _matchedRow: matched,
    _emailAction: emailAction,
  },
}];

const meta = $('Evaluate & Respond').item.json;
const row = meta._matchedRow || {};
// Mirrors src/utils/text.ts's toTitleCase so a test send previews the
// same casing a real send would use, regardless of how the name is
// actually capitalized in the database.
function toTitleCase(s) {
  return (s || '').toString().toLowerCase().split(' ').map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(' ');
}
function fill(template) {
  return (template || '')
    .replace(/{{\s*first_name\s*}}/gi, toTitleCase(row.first_name) || 'there')
    .replace(/{{\s*last_name\s*}}/gi, toTitleCase(row.last_name))
    .replace(/{{\s*deal_name\s*}}/gi, row.name || 'Sample Deal')
    .replace(/{{\s*owner_name\s*}}/gi, toTitleCase(row.owner_name) || 'your account team')
    .replace(/{{\s*proposal_link\s*}}/gi, row.proposal_token ? `#proposal-${row.proposal_token}` : '#')
    // A real send clones the referenced template into an actual DB row via
    // Automation Engine.json — a Test send deliberately does NOT (this whole
    // flow is a dry run with no side effects), so these can't resolve to a
    // real link here. Show a clearly-labeled placeholder instead of silently
    // deleting the token via the generic {{ }} strip below, which is what
    // made proposal/contract links vanish from test sends entirely.
    .replace(/{{\s*proposal_template:\d+\s*}}/gi, '[TEST — a real, unique proposal link appears here on an actual send]')
    .replace(/{{\s*contract_template:\d+\s*}}/gi, '[TEST — a real, unique contract link appears here on an actual send]')
    // Safety net matching Automation Engine.json's Prepare Email — strips
    // any OTHER unresolved "{{ }}" so a real send's preview matches what
    // actually goes out instead of risking the "undefined" corruption
    // n8n's own expression engine causes downstream on Send Test Email's
    // `={{ $json.body }}` field.
    .replace(/{{[^{}]*}}/g, '');
}
return [{ json: { to: meta._testEmail, subject: '[TEST] ' + fill(meta._emailAction.action_config.subject), body: fill(meta._emailAction.action_config.body) } }];
